import{_ as a,o as e,c as i,ao as t}from"./chunks/framework.B7UvRKha.js";const k=JSON.parse('{"title":"Setting up Slack for Ship of Tools","description":"","frontmatter":{},"headers":[],"relativePath":"guide/chat-setup.md","filePath":"guide/chat-setup.md","lastUpdated":null}'),n={name:"guide/chat-setup.md"};function o(h,s,l,p,r,d){return e(),i("div",null,[...s[0]||(s[0]=[t(`<h1 id="Setting-up-Slack-for-Ship-of-Tools" tabindex="-1">Setting up Slack for Ship of Tools <a class="header-anchor" href="#Setting-up-Slack-for-Ship-of-Tools" aria-label="Permalink to &quot;Setting up Slack for Ship of Tools {#Setting-up-Slack-for-Ship-of-Tools}&quot;">​</a></h1><p>Ship of Tools can show a Slack channel next to each project, in the Chat drawer (<code>Ctrl+K</code>, <code>Cmd+K</code> on a Mac), and post to it. This page sets that up from nothing. You need to be allowed to add apps to your Slack workspace.</p><p>The chat runs on one computer: the one that runs your project sessions. If you use Ship of Tools on one computer, that is the one. If you have several, it is the one your <code>hosts.toml</code> names as <code>hub</code>. Every window shows the chat of that computer. The files below go on it.</p><h2 id="1.-Make-a-Slack-app" tabindex="-1">1. Make a Slack app <a class="header-anchor" href="#1.-Make-a-Slack-app" aria-label="Permalink to &quot;1. Make a Slack app {#1.-Make-a-Slack-app}&quot;">​</a></h2><p>Ship of Tools talks to Slack as an app of your own.</p><ol><li><p>Go to <a href="https://api.slack.com/apps" target="_blank" rel="noreferrer">api.slack.com/apps</a>, choose <strong>Create New App</strong>, then <strong>From a manifest</strong>, and pick your workspace.</p></li><li><p>Paste this, then <strong>Create</strong>:</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">display_information</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  name</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">Ship of Tools</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">features</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  bot_user</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    display_name</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">Ship of Tools</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    always_online</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">oauth_config</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  scopes</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    bot</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">      - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">channels:history</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">      - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">channels:read</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">      - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">groups:history</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">      - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">groups:read</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">      - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">users:read</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">      - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">chat:write</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">      - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">chat:write.customize</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">settings</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  event_subscriptions</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    bot_events</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">      - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">message.channels</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">      - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">message.groups</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  socket_mode_enabled</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span></span></code></pre></div><p>What these allow: read public and private channels the app is in and their names, look up people&#39;s names, post under your name, and hear about new messages over a connection Ship of Tools opens itself (so nothing needs to reach your computer from outside).</p></li><li><p><strong>Install App</strong> → <strong>Install to Workspace</strong> → <strong>Allow</strong>. Copy the <strong>Bot User OAuth Token</strong>; it starts with <code>xoxb-</code>.</p></li><li><p><strong>Basic Information</strong> → <strong>App-Level Tokens</strong> → <strong>Generate Token and Scopes</strong>. Give it any name, add the scope <code>connections:write</code>, and <strong>Generate</strong>. Copy the token; it starts with <code>xapp-</code>.</p></li></ol><p>Keep both tokens private, like passwords.</p><h2 id="2.-Find-the-IDs" tabindex="-1">2. Find the IDs <a class="header-anchor" href="#2.-Find-the-IDs" aria-label="Permalink to &quot;2. Find the IDs {#2.-Find-the-IDs}&quot;">​</a></h2><p>Open Slack in a web browser and click the channel. The address looks like <code>https://app.slack.com/client/T0123ABCD/C0456EFGH</code>:</p><ul><li><p><code>T0123ABCD</code> is your <strong>workspace ID</strong>.</p></li><li><p><code>C0456EFGH</code> is the <strong>channel ID</strong>. (In the Slack app it is also at the bottom of the channel&#39;s details.)</p></li></ul><h2 id="3.-Add-the-app-to-the-channel" tabindex="-1">3. Add the app to the channel <a class="header-anchor" href="#3.-Add-the-app-to-the-channel" aria-label="Permalink to &quot;3. Add the app to the channel {#3.-Add-the-app-to-the-channel}&quot;">​</a></h2><p>In the channel, type <code>/invite @Ship of Tools</code> (the name you gave the app). Slack lets the app read and post only in channels it has been added to, private ones included.</p><h2 id="4.-Tell-Ship-of-Tools" tabindex="-1">4. Tell Ship of Tools <a class="header-anchor" href="#4.-Tell-Ship-of-Tools" aria-label="Permalink to &quot;4. Tell Ship of Tools {#4.-Tell-Ship-of-Tools}&quot;">​</a></h2><p>On the computer that runs your sessions, in Ship of Tools&#39; settings folder (<code>~/.config/sot</code> on Linux and macOS, <code>%LOCALAPPDATA%\\sot\\config</code> on Windows), make two files.</p><p><code>chat-secrets.toml</code>, with your workspace ID and the two tokens:</p><div class="language-toml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">toml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">workspace = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;T0123ABCD&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">bot_token = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;xoxb-...&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">app_token = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;xapp-...&quot;</span></span></code></pre></div><p>On Linux or macOS, make it readable only by you: <code>chmod 600 ~/.config/sot/chat-secrets.toml</code>.</p><p><code>chat.toml</code>, which says which channel goes with which project folder:</p><div class="language-toml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">toml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">workspace = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;T0123ABCD&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">channels = [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;C0456EFGH&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[[</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mapping</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">folder = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;/home/you/projects/my-project&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">channel = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;C0456EFGH&quot;</span></span></code></pre></div><p><code>folder</code> is the project&#39;s folder as its session row shows it. On Windows, write the folder in single quotes: <code>folder = &#39;C:\\Users\\you\\projects\\my-project&#39;</code>.</p><h2 id="5.-Restart-and-open-it" tabindex="-1">5. Restart and open it <a class="header-anchor" href="#5.-Restart-and-open-it" aria-label="Permalink to &quot;5. Restart and open it {#5.-Restart-and-open-it}&quot;">​</a></h2><p>Restart Ship of Tools&#39; background service on that computer (on Linux: <code>systemctl --user restart sotd</code>). Your sessions keep running; their Julia REPLs start fresh. Then select the project in the window and press <code>Ctrl+K</code> (<code>Cmd+K</code> on a Mac). The first time you post, the window asks for the name to post under.</p><h2 id="Adding-another-project-later" tabindex="-1">Adding another project later <a class="header-anchor" href="#Adding-another-project-later" aria-label="Permalink to &quot;Adding another project later {#Adding-another-project-later}&quot;">​</a></h2><p>Find the channel&#39;s ID (step 2), add the app to the channel (step 3), then in <code>chat.toml</code> add the ID to <code>channels</code> and add another <code>[[mapping]]</code> with the project&#39;s folder and that channel, and restart (step 5). One channel per project.</p><h2 id="If-it-does-not-show" tabindex="-1">If it does not show <a class="header-anchor" href="#If-it-does-not-show" aria-label="Permalink to &quot;If it does not show {#If-it-does-not-show}&quot;">​</a></h2><p>The Chat drawer&#39;s title says what is wrong. <code>the row&#39;s folder maps to no channel</code> means the folder in <code>chat.toml</code> is not exactly the row&#39;s folder. <code>the hub has no usable chat configuration</code> means a file was refused: the background service&#39;s log says which file and which line (<code>sotd log-path</code> prints where the log is). A token or ID is never printed in the log. The full rules for both files are in <a href="/ship-of-tools/dev/ref/config#chat.toml-and-chat-secrets.toml">the configuration reference</a>.</p>`,26)])])}const E=a(n,[["render",o]]);export{k as __pageData,E as default};
